package com.example.evcharging.payment.infrastructure;
import com.example.evcharging.framework.context.RequestContext;import com.example.evcharging.payment.application.PaymentApplicationService;import com.example.evcharging.payment.domain.PaymentChannel;import com.example.evcharging.payment.gateway.PaymentGateway;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import java.util.*;
@Component public class PaymentUnknownRecoveryJob {private final JdbcTemplate jdbc;private final PaymentApplicationService service;private final Map<PaymentChannel,PaymentGateway> gateways;public PaymentUnknownRecoveryJob(JdbcTemplate j,PaymentApplicationService s,List<PaymentGateway> gs){jdbc=j;service=s;Map<PaymentChannel,PaymentGateway> m=new EnumMap<>(PaymentChannel.class);gs.forEach(g->m.put(g.channel(),g));gateways=Map.copyOf(m);}@Scheduled(fixedDelayString="${charging.payment.unknown-query-delay-ms:5000}") public void scan(){var rows=jdbc.query("SELECT tenant_id,payment_no,channel,channel_trade_no FROM payment_order WHERE status='UNKNOWN' ORDER BY update_time LIMIT 100",(rs,n)->new Row(rs.getLong(1),rs.getString(2),rs.getString(3),rs.getString(4)));for(Row r:rows){PaymentGateway g=gateways.get(PaymentChannel.valueOf(r.channel));if(g==null)continue;try{RequestContext.set(r.tenantId,"payment-recovery:"+r.paymentNo);service.markQueryResult(r.paymentNo,g.query(r.paymentNo,r.channelTradeNo));}finally{RequestContext.clear();}}}private record Row(long tenantId,String paymentNo,String channel,String channelTradeNo){}}
